    '<strong>OAuth callback URL</strong> (musí být v Meta App → Facebook Login → Settings → Valid OAuth Redirect URIs):' => '<strong>OAuth callback URL</strong> (musí byť v Meta App → Facebook Login → Settings → Valid OAuth Redirect URIs):',
