    'Client ID nevypadá platně (má tvar 1234-abc.apps.googleusercontent.com).' => 'Client ID nevyzerá platne (má tvar 1234-abc.apps.googleusercontent.com).',
    'Vyplňte i Client secret.' => 'Vyplňte aj Client secret.',
    'Google OAuth klient je uložený.' => 'Google OAuth klient je uložený.',
    'Převzat Google OAuth klient z napojení „{name}“.' => 'Prevzatý Google OAuth klient z napojenia „{name}“.',
